def assign_proposal_versions(apps, schema_editor):
    Shipment = apps.get_model("logistics", "Shipment")
    FeeProposal = apps.get_model("logistics", "ShipmentFeeProposal")
    for shipment_id, proposal_group in groupby(
        FeeProposal.objects.order_by("shipment_id", "created_at", "pk").iterator(
            chunk_size=500
        ),
        key=lambda proposal: proposal.shipment_id,
    ):
        proposals = list(proposal_group)
        for version, proposal in enumerate(proposals, start=1):
            proposal.version = version
        current_proposal = proposals[-1]
        now = timezone.now()
        for proposal in proposals:
            if (
                proposal.status == "proposed"
                and proposal.pk != current_proposal.pk
            ):
                proposal.status = "superseded"
                proposal.responded_at = now
        FeeProposal.objects.bulk_update(
            proposals, ["version", "status", "responded_at"]
        )
        Shipment.objects.filter(pk=shipment_id).update(
            current_fee_proposal_version=len(proposals)
        )


